function embossProcess(data,w,h,opts){
  opts=opts||{};
  var az=opts.azimuth!=null?opts.azimuth:45;
  var str=opts.strength!=null?opts.strength:1;
  var lx=Math.cos(az*Math.PI/180), ly=Math.sin(az*Math.PI/180);
  var maxAbs=0;
  for(var oy=-1;oy<=1;oy++) for(var ox=-1;ox<=1;ox++){
    if(ox===0&&oy===0) continue;
    maxAbs+=Math.abs(ox*lx+oy*ly);
  }
  if(maxAbs<1e-9) maxAbs=1;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var sum=0;
    for(var oy2=-1;oy2<=1;oy2++) for(var ox2=-1;ox2<=1;ox2++){
      if(ox2===0&&oy2===0) continue;
      var sx=x+ox2, sy=y+oy2;
      if(sx<0)sx=0; else if(sx>w-1)sx=w-1;
      if(sy<0)sy=0; else if(sy>h-1)sy=h-1;
      var i2=(sy*w+sx)*4;
      var g=0.299*data[i2]+0.587*data[i2+1]+0.114*data[i2+2];
      sum+=(ox2*lx+oy2*ly)*g;
    }
    var v=128 + (sum/maxAbs)*127*str;
    if(v<0)v=0; else if(v>255)v=255;
    var i=(y*w+x)*4; out[i]=v;out[i+1]=v;out[i+2]=v;out[i+3]=data[i+3];
  }
  return out;
}

var EXPORTS={embossProcess:embossProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EmbossForgePure = EXPORTS; }
